        :param state_dict: Dict[str, Any]. A dictionary containing the state to be loaded into the StreamingDataset instance. It maps state keys to their corresponding values.
        :return: No return values.
        """

        expected_keys = ['_state_dict']

        for key in expected_keys:
            if key not in state_dict:
                raise KeyError(f"Expected key '{key}' not found in the provided state dictionary.")

        for key in state_dict:
            if key not in expected_keys:
                raise KeyError(f"Unexpected key '{key}' found in the provided state dictionary.")

        for key in expected_keys:
            setattr(self, key, state_dict[key])
