from typing import Optional, Dict, List, Union
from collections import defaultdict
import numpy as np
from searcharray.postings import SearchArray
from searcharray.similarity import Similarity

def edismax(frame: pd.DataFrame,
            q: str,
            qf: List[str],
            mm: Optional[str] = None,
            pf: Optional[List[str]] = None,
            pf2: Optional[List[str]] = None,
            pf3: Optional[List[str]] = None,
            q_op: str = "OR",
            similarity: Similarity = default_bm25) -> Tuple[np.ndarray, str]:

    query_fields = {field: 1.0 for field in qf}
    num_search_terms = len(q.split())

    search_terms = defaultdict(list)
    for term in q.split():
        for field in qf:
            search_terms[field].append(term)

    if pf:
        for field in pf:
            query_fields[field] = 1.5

    if pf2:
        for field in pf2:
            query_fields[field] = 1.2

    if pf3:
        for field in pf3:
            query_fields[field] = 1.1

    query_fields = dict(sorted(query_fields.items()))

    scores = np.zeros(len(frame))

    for i, doc in enumerate(frame.index):
        doc_scores = np.zeros(num_search_terms)
        for j, (field, terms) in enumerate(search_terms.items()):
            if field not in query_fields:
                continue
            search_array = SearchArray(frame, field)
            doc_scores[j] = search_array.score(terms, similarity)
        scores[i] = similarity.combine(doc_scores, q_op)

    return scores,

